# Fix the backtracking approach
edges = []
for g in range(4):
    edges.append((3*g, 3*g+1))
    edges.append((3*g, 3*g+2))
    edges.append((3*g+1, 3*g+2))
for g in range(3):
    for i in range(3):
        edges.append((3*g+i, 3*(g+1)+i))

adj = [[] for _ in range(12)]
for idx, (u, v) in enumerate(edges):
    adj[u].append((v, idx))
    adj[v].append((u, idx))

def solve():
    labels = [-1] * 12
    used_labels = set()
    used_diffs = set()

    # Order vertices by degree (most constrained first)
    degrees = [(len(adj[i]), i) for i in range(12)]
    degrees.sort(reverse=True)
    order = [i for _, i in degrees]

    def backtrack(pos):
        if pos == 12:
            return True

        v = order[pos]

        for label in range(22):
            if label in used_labels:
                continue

            consistent = True
            new_diffs = []
            for neighbor, edge_idx in adj[v]:
                if labels[neighbor] != -1:
                    diff = abs(label - labels[neighbor])
                    if diff == 0 or diff in used_diffs:
                        consistent = False
                        break
                    new_diffs.append(diff)

            if not consistent:
                continue

            # Check for duplicate diffs among new edges
            if len(new_diffs) != len(set(new_diffs)):
                continue

            # Assign
            labels[v] = label
            used_labels.add(label)
            for diff in new_diffs:
                used_diffs.add(diff)

            if backtrack(pos + 1):
                return True

            # Unassign
            labels[v] = -1
            used_labels.remove(label)
            for diff in new_diffs:
                used_diffs.remove(diff)

        return False

    if backtrack(0):
        return labels
    return None

result = solve()
if result:
    print(f"Solution: {result}")
    edge_diffs = []
    for u, v in edges:
        diff = abs(result[u] - result[v])
        edge_diffs.append(diff)
    print(f"Edge differences: {sorted(edge_diffs)}")
    print(f"All distinct: {len(set(edge_diffs)) == len(edge_diffs)}")
else:
    print("UNSATISFIABLE")
